import { expect, test } from "@playwright/test";
import { e2eName, STORAGE_STATE } from "./roles";

/**
 * Creating an employee and reading them back.
 *
 * The point is the seam: the form writes through a Server Action, the employee
 * number is generated by a counter, and the profile then assembles seventeen
 * permission-gated queries. Each piece has been tested on its own; this is the
 * only thing that proves they line up.
 */
test.describe("employee lifecycle", () => {
  test.use({ storageState: STORAGE_STATE.hr });

  test("creates an employee, then reads them back on the profile", async ({ page }) => {
    const firstName = e2eName("Lifecycle");
    const lastName = "Tester";

    await page.goto("/people/employees/new");

    await page.getByRole("textbox", { name: "First name", exact: true }).fill(firstName);
    await page.getByRole("textbox", { name: "Last name", exact: true }).fill(lastName);
    await page.getByRole("combobox", { name: "Gender", exact: true }).click();
    await page.getByRole("option", { name: "Male", exact: true }).click();
    await page.getByRole("textbox", { name: "Nationality", exact: true }).fill("PK");
    await page.getByRole("textbox", { name: "Joining date", exact: true }).fill("2026-01-15");

    await page.getByRole("button", { name: /create employee/i }).click();

    // The action redirects to the new profile; the id in the URL is the proof
    // that a record was written, not just that the form submitted.
    await page.waitForURL(
      (url) =>
        /^\/people\/employees\/[a-z0-9]+$/i.test(url.pathname) &&
        !url.pathname.endsWith("/new"),
      { timeout: 30_000 },
    );

    await expect(
      page.getByRole("heading", { name: new RegExp(firstName, "i") }),
    ).toBeVisible();

    // An employee number is generated server-side; a blank one would mean the
    // counter never ran.
    await expect(page.getByText(/EMP-\d+/)).toBeVisible();

    // The tabs HR is entitled to must render — this is the seventeen-query
    // assembly actually running rather than throwing.
    for (const tab of ["Overview", "Employment", "Documents", "Timesheet"]) {
      await expect(page.getByRole("tab", { name: new RegExp(tab, "i") })).toBeVisible();
    }

    // History is audit.view, which HR does not hold. Its absence here is the
    // per-tab gating working, not a missing feature.
    await expect(page.getByRole("tab", { name: /^History$/ })).toHaveCount(0);
  });

  test("refuses to mark someone as left without a last working date", async ({ page }) => {
    const firstName = e2eName("Leaver");

    await page.goto("/people/employees/new");
    await page.getByRole("textbox", { name: "First name", exact: true }).fill(firstName);
    await page.getByRole("textbox", { name: "Last name", exact: true }).fill("Tester");
    await page.getByRole("combobox", { name: "Gender", exact: true }).click();
    await page.getByRole("option", { name: "Female", exact: true }).click();
    await page.getByRole("textbox", { name: "Nationality", exact: true }).fill("IN");
    await page.getByRole("textbox", { name: "Joining date", exact: true }).fill("2026-01-15");

    // TERMINATED with no leaving date is the rule that had no enforcement path
    // until the audit; offboarding and the leavers report both key off it.
    await page.getByRole("combobox", { name: "Status", exact: true }).click();
    await page.getByRole("option", { name: "Terminated" }).click();

    await page.getByRole("button", { name: /create employee/i }).click();

    await expect(
      page.getByText(/last working date is required when an employee leaves/i),
    ).toBeVisible();

    // And it must not have been created.
    await expect(page).toHaveURL(/\/people\/employees\/new/);
  });
});
